import {site, projects, weeks, resources} from './data.js';

const root = document.querySelector('#app');
const depth = Number(document.body.dataset.depth || 0);
const base = '../'.repeat(depth);
const page = document.body.dataset.page || 'home';
const projectId = document.body.dataset.project;
const esc = v => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const href = key => `${base}${key === 'home' ? '' : key + '/'}index.html`;
const pHref = p => `${base}projects/${p.id}/index.html`;
const dHref = p => `${base}teams/${p.id}/index.html`;

function shell(content, crumb=''){
  document.documentElement.style.setProperty('--accent', projectId ? projects.find(p=>p.id===projectId)?.color : '#b85c38');
  root.innerHTML=`<a class="skip" href="#main">跳到主要內容</a><button class="menu-button" aria-label="開啟導覽選單" aria-expanded="false">☰</button><div class="mobile-overlay"></div><aside class="sidebar"><a class="brand" href="${href('home')}"><small>COURSE SHOWCASE</small><strong>${site.title}</strong></a><nav class="nav" aria-label="主要導覽">${site.nav.map(([k,n])=>`<a href="${href(k)}" ${page===k?'aria-current="page"':''}>${n}</a>`).join('')}</nav><p class="side-note">講師｜${site.instructor}<br>靜態課程展示網站</p></aside><div class="main"><main id="main" class="content" tabindex="-1">${crumb?`<nav class="breadcrumbs" aria-label="麵包屑">${crumb}</nav>`:''}${content}<footer class="footer">${site.title}｜講師 ${site.instructor}<br>${site.notice}</footer></main></div>`;
  const button=document.querySelector('.menu-button');
  const close=()=>{document.body.classList.remove('menu-open');button.setAttribute('aria-expanded','false');button.textContent='☰'};
  button.addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');button.setAttribute('aria-expanded',String(open));button.textContent=open?'×':'☰'});
  document.querySelector('.mobile-overlay').addEventListener('click',close);
  document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
}

const notice=()=>`<div class="notice" role="note"><strong>展示內容說明</strong><br>${site.notice}</div>`;
const projectCards=(limit=10)=>`<div class="grid">${projects.slice(0,limit).map(p=>`<article class="card card-link" style="--accent:${p.color}"><div class="card-top"><span class="team-id">${p.team}</span><span aria-hidden="true">↗</span></div><h3>${p.name}</h3><p>${p.tagline}</p><div class="tags">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><a class="button" href="${pHref(p)}" aria-label="開啟 ${p.name} 專案">查看專案</a></article>`).join('')}</div>`;

function renderHome(){shell(`<section class="hero"><div><p class="eyebrow">AI × Humanities × Making</p><h1>${site.title}</h1><p class="lead">從人的需求與人文問題出發，透過訪談、觀察、資料整理、需求定義與 AI 協作，開發可以實際操作的數位應用。</p><div class="actions"><a class="button" href="${href('teams')}">查看分組名單</a><a class="button secondary" href="${href('showcase')}">瀏覽期末成果</a></div></div><aside class="hero-aside"><span>講師</span><br><b>${site.instructor}</b><p>引導人文觀察、問題定義、AI 協作與數位實作。</p></aside></section><section class="section"><div class="section-head"><div><p class="eyebrow">Learning focus</p><h2>不只做出成品，也說清楚判斷</h2></div><p>課程重視需求證據、規模控制、版本修改與人的判斷，讓數位工具回應具體使用情境。</p></div><div class="grid"><article class="card"><span class="stat">01</span><h3>觀察與定義</h3><p>區分現象、需求與假設，把寬廣題目收斂為可驗證問題。</p></article><article class="card"><span class="stat">02</span><h3>協作與實作</h3><p>用 PRD、PLAN 與版本紀錄和 AI 協作，保留人的查核與取捨。</p></article><article class="card"><span class="stat">03</span><h3>測試與反思</h3><p>設計具體任務、觀察操作困難，依證據修正而非只美化外觀。</p></article></div></section><section class="section"><div class="section-head"><div><p class="eyebrow">10 projects</p><h2>數位應用專案</h2></div><a href="${href('showcase')}">查看全部成果 →</a></div>${projectCards(3)}</section>${notice()}`)}
function renderInstructor(){shell(`<section class="hero"><div><p class="eyebrow">Instructor</p><h1>申惠豐</h1><p class="lead">在本課程中，講師的角色是陪伴學生把人文觀察轉化為可操作的問題，並在 AI 協作與實作過程中持續追問：證據是什麼、誰做決定、工具如何回應人的需要。</p></div><aside class="hero-aside"><b>引導，而非替代判斷</b><p>聚焦人文觀察、問題定義、協作方法與數位實作。</p></aside></section><section class="section"><div class="grid"><article class="card"><h3>看見人的處境</h3><p>協助從訪談、觀察與文本中辨識具體使用者、情境與限制。</p></article><article class="card"><h3>建立可說明的決策</h3><p>要求需求、功能與修改都有理由，並辨識 AI 建議的限制。</p></article><article class="card"><h3>控制可完成的範圍</h3><p>以最小核心流程為單位，讓一學期專題能真正操作與驗證。</p></article></div></section><div class="notice">本頁僅說明講師在課程中的教學引導角色，不包含未經提供的學歷、經歷、著作、獎項或聯絡資訊。</div>`,`<a href="${href('home')}">首頁</a><span>/</span><span>講師</span>`)}
function renderCourse(){shell(`<section class="hero"><div><p class="eyebrow">18-week syllabus</p><h1>課程內容</h1><p class="lead">從需求探索到靜態數位應用部署，以小步驟完成一個能操作、能測試、也能解釋設計判斷的專案。</p></div></section>${notice()}<section class="section"><div class="timeline">${weeks.map(([n,t])=>`<article class="week"><b>W${n}</b><span>${t}</span></article>`).join('')}</div></section>`,`<a href="${href('home')}">首頁</a><span>/</span><span>課程內容</span>`)}
function renderGrading(){const scores=[['問題理解與人文脈絡','15%'],['需求探索與設計判斷','15%'],['數位應用完成度','20%'],['使用者測試與證據修正','15%'],['AI 協作中的查核與判斷','15%'],['PRD、PLAN 與過程紀錄','15%'],['成果展示與學習反思','5%']];shell(`<section class="hero"><div><p class="eyebrow">Course guide</p><h1>課程說明與評分標準</h1><p class="lead">目標是能從人文需求提出可驗證的數位解法，建立核心流程，並清楚交代 AI 協作中由人做出的判斷。</p></div></section><section class="section"><div class="detail-grid"><article class="card"><h2>課程目標</h2><ul><li>以訪談、觀察或資料整理辨識需求。</li><li>用 PRD 與 PLAN 控制範圍並管理版本。</li><li>完成可操作、可測試的前端應用原型。</li><li>查核 AI 產出並說明採用、修改或拒絕的理由。</li></ul></article><article class="card"><h2>作業要求</h2><ul><li>需求與問題定義紀錄。</li><li>PRD、PLAN 與介面流程。</li><li>至少一條完整核心操作。</li><li>版本修改、模擬測試與成果說明。</li></ul></article></div></section><section class="section"><h2>示例評分比例</h2><div class="card">${scores.map(([n,v])=>`<div class="score"><span>${n}</span><strong>${v}</strong></div>`).join('')}<div class="score"><b>合計</b><strong>100%</strong></div></div><p>評量不只看成品外觀，也看問題理解、證據、功能取捨、測試修正與過程紀錄。</p></section>${notice()}`,`<a href="${href('home')}">首頁</a><span>/</span><span>課程說明與評分標準</span>`)}
function renderShowcase(){shell(`<section class="hero"><div><p class="eyebrow">Final showcase</p><h1>期末成果發表</h1><p class="lead">10 組不同的人文數位應用提案。每個入口都包含問題定義、開發過程、測試示例與可操作原型。</p></div><aside class="hero-aside"><span class="stat">10</span><b>組核心流程</b><p>以 2–3 項功能控制專題規模。</p></aside></section>${notice()}<section class="section">${projectCards()}</section>`,`<a href="${href('home')}">首頁</a><span>/</span><span>期末成果發表</span>`)}
function renderTeams(){shell(`<section class="hero"><div><p class="eyebrow">Teams</p><h1>分組名單</h1><p class="lead">共 10 組。姓名僅用於呈現指定分組，不含系級、學號或其他個人資料。</p></div></section>${notice()}<section class="section"><div class="grid two">${projects.map(p=>`<article class="card" style="--accent:${p.color}"><span class="team-id">${p.team}</span><h2>${p.name}</h2><p><b>組員：</b>${p.members.join('、')}</p><p>${p.tagline}</p><div class="actions"><a class="button" href="${pHref(p)}">專案網站</a><a class="button secondary" href="${dHref(p)}">小組檔案</a></div></article>`).join('')}</div></section>`,`<a href="${href('home')}">首頁</a><span>/</span><span>分組名單</span>`)}
function renderResources(){shell(`<section class="hero"><div><p class="eyebrow">Toolkit</p><h1>開發工具與資源</h1><p class="lead">從編輯、版本管理、介面設計到部署的官方或穩定學習入口。外部連結會在新分頁開啟。</p></div></section><section class="section"><div class="grid two">${resources.map(([n,d,u])=>`<article class="card card-link"><h3>${n}</h3><p>${d}</p><a href="${u}" target="_blank" rel="noopener noreferrer">開啟官方資源 ↗</a></article>`).join('')}</div></section><section class="callout"><h2>AI 協作原則</h2><p>先定義任務與驗收條件，再請工具協助拆解、產生草稿或解釋錯誤。任何生成的事實、引文、程式與設計建議都需由人查核；不要輸入未經同意的訪談個資或敏感資料。</p></section>`,`<a href="${href('home')}">首頁</a><span>/</span><span>開發工具與資源</span>`)}

function renderProject(){const p=projects.find(x=>x.id===projectId);if(!p)return render404();document.title=`${p.name}｜${site.title}`;const demoLabels=['起始畫面','核心操作','結果與整理'];const demoGallery=`<section class="section"><div class="section-head"><div><p class="eyebrow">Mobile demo UI</p><h2>手機版 DEMO</h2></div><p>三張示意圖呈現核心流程的起始、操作與結果狀態；圖像為 AI 生成的介面概念稿，實際操作請使用下方原型。</p></div><div class="demo-gallery">${demoLabels.map((label,i)=>`<figure><img src="${base}assets/demos/${p.id}-${String(i+1).padStart(2,'0')}.png" alt="${p.name} 手機版 DEMO：${label}" loading="lazy" width="942" height="1674"><figcaption>0${i+1}｜${label}</figcaption></figure>`).join('')}</div></section>`;shell(`<section class="project-hero hero" style="--accent:${p.color}"><div><p class="eyebrow">${p.team} · Digital humanities project</p><h1>${p.name}</h1><p class="lead">${p.tagline}</p><div class="project-meta"><span>組員｜${p.members.join('、')}</span><span>展示用模擬專案</span></div></div><aside class="hero-aside"><b>核心操作</b><p>${p.flow}</p></aside></section>${notice()}<section class="section"><div class="detail-grid"><article class="card"><h2>使用者與問題</h2><h3>具體使用者</h3><p>${p.user}</p><h3>需要解決的問題</h3><p>${p.problem}</p></article><article class="card"><h2>需求探索與定義</h2><p>${p.discovery}</p><h3>核心功能</h3><ul>${p.features.map(x=>`<li>${x}</li>`).join('')}</ul></article><article class="card wide"><h2>PRD 摘要</h2><div class="grid"><div><h3>目標</h3><p>${p.tagline}</p></div><div><h3>功能範圍</h3><p>${p.scope}</p></div><div><h3>不做事項</h3><p>${p.no}</p></div></div><h3>驗收條件</h3><p>${p.acceptance}</p></article><article class="card"><h2>PLAN 摘要</h2><ol class="number-list">${p.plan.map(x=>`<li>${x}</li>`).join('')}</ol></article><article class="card"><h2>版本修改</h2><h3>一項具體困難</h3><p>${p.difficulty}</p><p><b>修改前後：</b>從阻礙或誤導使用的流程，改為可理解、可回復且符合專案目的的核心互動。</p></article><article class="card"><h2>AI 協作與人的判斷</h2><p>${p.ai}</p></article><article class="card"><h2>模擬使用者測試</h2><p>${p.test}</p><p class="team-id">此為測試情境示例，非實際受試紀錄。</p></article></div></section>${demoGallery}<section class="section" id="prototype"><div class="section-head"><div><p class="eyebrow">Interactive prototype</p><h2>可操作的應用原型</h2></div><p>${p.result}</p></div><div id="prototype-root"></div></section><section class="section"><div class="callout"><h2>成果與學習反思</h2><p>${p.result}</p><p>${p.reflection}</p></div><div class="actions"><a class="button" href="${dHref(p)}">閱讀小組檔案</a><a class="button secondary" href="${href('teams')}">返回分組名單</a><a class="button ghost" href="${href('showcase')}">返回成果總覽</a></div></section>`,`<a href="${href('home')}">首頁</a><span>/</span><a href="${href('showcase')}">成果總覽</a><span>/</span><span>${p.name}</span>`);import('./prototypes.js').then(m=>m.mountPrototype(p));}

function renderDocs(){const p=projects.find(x=>x.id===projectId);if(!p)return render404();document.title=`${p.team} 小組檔案｜${site.title}`;shell(`<section class="hero"><div><p class="eyebrow">${p.team} · Project files</p><h1>${p.name} 小組檔案</h1><p class="lead">可直接閱讀、列印或另存 PDF 的專案文件彙整。所有內容均為展示用模擬資料。</p></div></section>${notice()}<section class="section"><article class="card"><h2>01 專案企畫書／PRD</h2><table class="doc-table"><tr><th>目標</th><td>${p.tagline}</td></tr><tr><th>使用者</th><td>${p.user}</td></tr><tr><th>問題</th><td>${p.problem}</td></tr><tr><th>功能範圍</th><td>${p.scope}</td></tr><tr><th>不做事項</th><td>${p.no}</td></tr><tr><th>驗收條件</th><td>${p.acceptance}</td></tr></table></article></section><section class="section"><article class="card"><h2>02 開發計畫</h2><ol class="number-list">${p.plan.map(x=>`<li>${x}</li>`).join('')}</ol></article></section><section class="section"><div class="grid two"><article class="card"><h2>03 開發與修改紀錄</h2><p>${p.difficulty}</p><p>版本紀錄示例：v0.1 紙上流程 → v0.2 核心互動 → v0.3 依模擬測試修正提示與狀態。</p></article><article class="card"><h2>04 模擬測試紀錄</h2><p>${p.test}</p><p class="team-id">非實際調查或受試資料。</p></article></div></section><section class="section"><article class="callout"><h2>05 成果說明</h2><p>${p.result}</p><p>${p.reflection}</p></article><div class="actions"><a class="button" href="${pHref(p)}">開啟專案與原型</a><button class="button secondary" type="button" onclick="window.print()">列印／另存 PDF</button><a class="button ghost" href="${href('teams')}">返回分組名單</a></div></section>`,`<a href="${href('home')}">首頁</a><span>/</span><a href="${href('teams')}">分組名單</a><span>/</span><span>${p.team} 小組檔案</span>`)}
function render404(){shell(`<section class="hero"><div><p class="eyebrow">404</p><h1>找不到這個頁面</h1><p class="lead">網址可能已變更，請回到首頁繼續瀏覽。</p><a class="button" href="${href('home')}">返回首頁</a></div></section>`)}

({home:renderHome,instructor:renderInstructor,course:renderCourse,grading:renderGrading,showcase:renderShowcase,teams:renderTeams,resources:renderResources,project:renderProject,docs:renderDocs}[page]||render404)();
